INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3414684, 475873, 73884, '<td valign="top">I knew there will be quite a few ice/fire shots, but this is the best!</td>', 'I knew there will be quite a few ice/fire shots, but this is the best!', '2007-02-28 17:02:36.000000', NULL, 1),
(3414696, 475198, 73929, '<td valign="top">hmmm - blurry AND not rotated!</td>', 'hmmm - blurry AND not rotated!', '2007-02-28 17:05:03.000000', NULL, 1),
(3414699, 476398, 6388, '<td valign="top">nice clean processing - great use of directional lighting to emphasize the diagonals.<br/> <br/>edited to add - even more impressive now that i know it was a self portrait.  impressive that you were able to balance the ice and release the shutter.<br/><br/><i>Message edited by author 2007-03-09 02:37:20.</i></td>', 'nice clean processing - great use of directional lighting to emphasize the diagonals. edited to add - even more impressive now that i know it was a self portrait.  impressive that you were able to balance the ice and release the shutter.', '2007-02-28 17:06:22.000000', '2007-03-09 02:37:20.000000', 1),
(3414700, 475985, 73235, '<td valign="top">seem to me overexposed, no details on the ice cubes</td>', 'seem to me overexposed, no details on the ice cubes', '2007-02-28 17:06:50.000000', NULL, 1),
(3414701, 473016, 2000, '<td valign="top">Cute title, and nice shot.  I like the detail in the ice, and I would like to see more of it (and less of the water) just to emphasize the focal point.</td>', 'Cute title, and nice shot.  I like the detail in the ice, and I would like to see more of it (and less of the water) just to emphasize the focal point.', '2007-02-28 17:06:53.000000', NULL, 1),
(3414702, 474433, 73564, '<td valign="top">Nice clear shot!</td>', 'Nice clear shot!', '2007-02-28 17:07:03.000000', NULL, 1),
(3414705, 476549, 73235, '<td valign="top">cool set up. did you do that just for this picture? nice work</td>', 'cool set up. did you do that just for this picture? nice work', '2007-02-28 17:08:15.000000', NULL, 1),
(3414706, 476796, 2000, '<td valign="top">Fun title, and an interesting take on a well-known phrase.  The ice holds its own here against the watch, and I like that aspect of the photo.</td>', 'Fun title, and an interesting take on a well-known phrase.  The ice holds its own here against the watch, and I like that aspect of the photo.', '2007-02-28 17:08:25.000000', NULL, 1),
(3414708, 474155, 73564, '<td valign="top">Man that is a really pretty picture!</td>', 'Man that is a really pretty picture!', '2007-02-28 17:09:34.000000', NULL, 1),
(3414710, 476084, 2000, '<td valign="top">Cool concept, but soft focus.</td>', 'Cool concept, but soft focus.', '2007-02-28 17:10:08.000000', NULL, 1),
(3414711, 476733, 73564, '<td valign="top">Yes it is nice!</td>', 'Yes it is nice!', '2007-02-28 17:10:19.000000', NULL, 1),
(3414713, 474914, 2000, '<td valign="top">Very cool capture... I''m thinking about whether I know the shot, but in any case I like the execution and the DOF.</td>', 'Very cool capture... I''m thinking about whether I know the shot, but in any case I like the execution and the DOF.', '2007-02-28 17:11:01.000000', NULL, 1),
