(3414718, 476862, 73235, '<td valign="top">appears washed out and has no depth</td>', 'appears washed out and has no depth', '2007-02-28 17:11:25.000000', NULL, 1),
(3414719, 476811, 2000, '<td valign="top">A natural frozen flower... I like the focus and the DOF in this shot.</td>', 'A natural frozen flower... I like the focus and the DOF in this shot.', '2007-02-28 17:11:55.000000', NULL, 1),
(3414723, 475804, 73564, '<td valign="top">Nice picture! good detail!</td>', 'Nice picture! good detail!', '2007-02-28 17:12:14.000000', NULL, 1),
(3414724, 476122, 2000, '<td valign="top">No ice, kinda grainy, and soft focus.  And why are chess men in the freezer?</td>', 'No ice, kinda grainy, and soft focus.  And why are chess men in the freezer?', '2007-02-28 17:12:24.000000', NULL, 1),
(3414728, 475327, 73564, '<td valign="top">Nice picture!</td>', 'Nice picture!', '2007-02-28 17:13:00.000000', NULL, 1),
(3414730, 476861, 2000, '<td valign="top">Fortunately birds are light and don''t need to worry about the thin ice.  This is a fun shot, and it definitely shows ice as the focal point.</td>', 'Fortunately birds are light and don''t need to worry about the thin ice.  This is a fun shot, and it definitely shows ice as the focal point.', '2007-02-28 17:13:25.000000', NULL, 1),
(3414731, 476000, 73564, '<td valign="top">Wow, amazing!</td>', 'Wow, amazing!', '2007-02-28 17:13:56.000000', NULL, 1),
(3414733, 475053, 2000, '<td valign="top">Ooh... the northern lights (?)... beautiful shot, with obvious ice.</td>', 'Ooh... the northern lights (?)... beautiful shot, with obvious ice.', '2007-02-28 17:14:34.000000', NULL, 1),
(3414735, 474429, 73564, '<td valign="top">Cool Shot!</td>', 'Cool Shot!', '2007-02-28 17:14:36.000000', NULL, 1),
(3414737, 476371, 73564, '<td valign="top">Cool detail!</td>', 'Cool detail!', '2007-02-28 17:14:58.000000', NULL, 1),
