(3414740, 475110, 73564, '<td valign="top">Nice clear picture!</td>', 'Nice clear picture!', '2007-02-28 17:15:37.000000', NULL, 1),
(3414741, 474369, 2000, '<td valign="top">Dizzying... a motion shot needs a fixed focal point, and there''s nothing fixed about this pic.</td>', 'Dizzying... a motion shot needs a fixed focal point, and there''s nothing fixed about this pic.', '2007-02-28 17:15:52.000000', NULL, 1),
(3414743, 475166, 73564, '<td valign="top">Nice picture!</td>', 'Nice picture!', '2007-02-28 17:16:23.000000', NULL, 1),
(3414744, 476851, 2000, '<td valign="top">Lovely, but I don''t see much ice for all the snow.  I like the concept, and it''s well executed.</td>', 'Lovely, but I don''t see much ice for all the snow.  I like the concept, and it''s well executed.', '2007-02-28 17:16:32.000000', NULL, 1),
(3414749, 476111, 2000, '<td valign="top">Neat detail and good idea.  I''d like to see a greater DOF, with both icicles in focus... otherwise I really like this shot.</td>', 'Neat detail and good idea.  I''d like to see a greater DOF, with both icicles in focus... otherwise I really like this shot.', '2007-02-28 17:17:49.000000', NULL, 1),
(3414753, 476520, 2000, '<td valign="top">I think I might want a print of this shot... I like the sunset and the detail in the ice, and especially the serenity of this shot.  Is the ice actually suspended above the water as it appears?</td>', 'I think I might want a print of this shot... I like the sunset and the detail in the ice, and especially the serenity of this shot.  Is the ice actually suspended above the water as it appears?', '2007-02-28 17:20:08.000000', NULL, 1),
(3414755, 476429, 2000, '<td valign="top">Please use the full 640px dimension on at least one side of your photo... it makes it so much easier to see.</td>', 'Please use the full 640px dimension on at least one side of your photo... it makes it so much easier to see.', '2007-02-28 17:20:55.000000', NULL, 1),
(3414759, 476370, 2000, '<td valign="top">Can''t see ice, Can''t see ice, Can''t see ice</td>', 'Can''t see ice, Can''t see ice, Can''t see ice', '2007-02-28 17:21:52.000000', NULL, 1),
(3414763, 475926, 2000, '<td valign="top">Oh, that darn blown out sunrise... otherwise a gorgeous shot.</td>', 'Oh, that darn blown out sunrise... otherwise a gorgeous shot.', '2007-02-28 17:22:28.000000', NULL, 1),
(3414764, 475894, 2000, '<td valign="top">the little bit of snow looks like a dog getting ready to run... but it''s just a little bit of snow.</td>', 'the little bit of snow looks like a dog getting ready to run... but it''s just a little bit of snow.', '2007-02-28 17:23:04.000000', NULL, 1),
(3414770, 475080, 73564, '<td valign="top">Cool Idea! Made me laugh!</td>', 'Cool Idea! Made me laugh!', '2007-02-28 17:23:44.000000', NULL, 1),
