(3414778, 474381, 2000, '<td valign="top">Cool perspective and nice lighting.  I also like the BW treatment here, as it seems to emphasize the cold.</td>', 'Cool perspective and nice lighting.  I also like the BW treatment here, as it seems to emphasize the cold.', '2007-02-28 17:26:11.000000', NULL, 1),
(3414780, 475687, 73564, '<td valign="top">One of the pretiest fire and ice shots!</td>', 'One of the pretiest fire and ice shots!', '2007-02-28 17:26:40.000000', NULL, 1),
(3414785, 475829, 2000, '<td valign="top">This is a nice idea, but I would like it a bit lighter and less grainy, and maybe better focus.  The snow may be a bit icy in this shot.</td>', 'This is a nice idea, but I would like it a bit lighter and less grainy, and maybe better focus.  The snow may be a bit icy in this shot.', '2007-02-28 17:28:08.000000', NULL, 1),
(3414793, 475166, 2000, '<td valign="top">Snow, not ice.</td>', 'Snow, not ice.', '2007-02-28 17:29:41.000000', NULL, 1),
