(3414798, 474116, 2000, '<td valign="top">Beautiful shot, but the ice is not the focal point of this photo.  None-the-less, I would recommend a print for this one.</td>', 'Beautiful shot, but the ice is not the focal point of this photo.  None-the-less, I would recommend a print for this one.', '2007-02-28 17:30:42.000000', NULL, 1),
(3414804, 476315, 2000, '<td valign="top">And you got an ice bite.  The focus seems a bit too soft here - maybe DOF too shallow to cover the whole ice cube.</td>', 'And you got an ice bite.  The focus seems a bit too soft here - maybe DOF too shallow to cover the whole ice cube.', '2007-02-28 17:32:18.000000', NULL, 1),
(3414806, 476340, 63218, '<td valign="top">big WOW factor here</td>', 'big WOW factor here', '2007-02-28 17:32:45.000000', NULL, 1),
(3414808, 476729, 2000, '<td valign="top">Nice action shot, lighting seems good, and all elements seem to belong there.  I''m trying to find what''s in focus, and I think it''s the skater''s knee.</td>', 'Nice action shot, lighting seems good, and all elements seem to belong there.  I''m trying to find what''s in focus, and I think it''s the skater''s knee.', '2007-02-28 17:33:54.000000', NULL, 1),
(3414812, 473624, 2000, '<td valign="top">Please use the full 640px dimension on one side of your shot when possible... it makes the photo so much easier to see.  That said, I like the concept, and I like that ice is the main focal point of the picture...  at this size, it looks a bit OOF.</td>', 'Please use the full 640px dimension on one side of your shot when possible... it makes the photo so much easier to see.  That said, I like the concept, and I like that ice is the main focal point of the picture...  at this size, it looks a bit OOF.', '2007-02-28 17:35:22.000000', NULL, 1),
(3414815, 476467, 2000, '<td valign="top">I''m kinda creeped out by this shot... but I like the concept and the focus is quite nice.</td>', 'I''m kinda creeped out by this shot... but I like the concept and the focus is quite nice.', '2007-02-28 17:36:12.000000', NULL, 1),
(3414818, 475983, 2000, '<td valign="top">Very pretty shot, and it''s obvious what you were going for.</td>', 'Very pretty shot, and it''s obvious what you were going for.', '2007-02-28 17:37:32.000000', NULL, 1),
(3414823, 476876, 2000, '<td valign="top">This is what I''m looking for in this challenge... obvious ice as the focal point, and a well executed view of it.</td>', 'This is what I''m looking for in this challenge... obvious ice as the focal point, and a well executed view of it.', '2007-02-28 17:38:55.000000', NULL, 1),
(3414825, 475198, 2000, '<td valign="top">Unrotated, OOF, snow not ice.</td>', 'Unrotated, OOF, snow not ice.', '2007-02-28 17:39:30.000000', NULL, 1),
(3414828, 476562, 2000, '<td valign="top">Wow... just wow.</td>', 'Wow... just wow.', '2007-02-28 17:40:02.000000', NULL, 1),
(3414833, 475035, 63218, '<td valign="top">sweet shot</td>', 'sweet shot', '2007-02-28 17:40:48.000000', NULL, 1),
(3414838, 475155, 2000, '<td valign="top">One or two steps to the right, and this would be an awesome framing shot.  Unfortunately, I see too much snow and no ice, but I like the shot anyway.</td>', 'One or two steps to the right, and this would be an awesome framing shot.  Unfortunately, I see too much snow and no ice, but I like the shot anyway.', '2007-02-28 17:41:32.000000', NULL, 1),
(3414841, 476598, 2000, '<td valign="top">Did you take this on Saturday?  I ask because I saw the moon like that on Saturday too.  Meanwhile, I like the concept and the focus, and the lighting seems right on.</td>', 'Did you take this on Saturday?  I ask because I saw the moon like that on Saturday too.  Meanwhile, I like the concept and the focus, and the lighting seems right on.', '2007-02-28 17:42:27.000000', NULL, 1),
(3414844, 474155, 2000, '<td valign="top">Fix the focus and this would be a 10 for ice... that''s my only comment.</td>', 'Fix the focus and this would be a 10 for ice... that''s my only comment.', '2007-02-28 17:43:13.000000', NULL, 1),
(3414848, 472984, 2000, '<td valign="top">The title is right on... that is definitely ice on a branch, and it''s in good focus with good lighting.</td>', 'The title is right on... that is definitely ice on a branch, and it''s in good focus with good lighting.', '2007-02-28 17:43:48.000000', NULL, 1),
