(3414855, 475062, 2000, '<td valign="top">Blown out, but I like the concept.</td>', 'Blown out, but I like the concept.', '2007-02-28 17:45:26.000000', NULL, 1),
(3414859, 475375, 2000, '<td valign="top">Time to call the gas company... cool concept, but it feels crooked.  What I mean is, your horizon is level, but since you''re looking from an angle, the verticals are off.</td>', 'Time to call the gas company... cool concept, but it feels crooked.  What I mean is, your horizon is level, but since you''re looking from an angle, the verticals are off.', '2007-02-28 17:47:44.000000', NULL, 1),
