(3425004, 474887, 41554, '<td valign="top">It does look very daunting. "Niflheimur" means the entrance to something akin to hell, right? Then you got it right...<br/>As a photo, it looks a bit too busy to me.</td>', 'It does look very daunting. "Niflheimur" means the entrance to something akin to hell, right? Then you got it right...As a photo, it looks a bit too busy to me.', '2007-03-03 06:13:41.000000', NULL, 1),
(3425006, 474899, 41554, '<td valign="top">This could be a great shot if the lighting was better (flash is too harsh on the eye, and some of the ice is blown), and if it was taken closer... it looks too busy.</td>', 'This could be a great shot if the lighting was better (flash is too harsh on the eye, and some of the ice is blown), and if it was taken closer... it looks too busy.', '2007-03-03 06:15:57.000000', NULL, 1),
(3425009, 475198, 55385, '<td valign="top">If you are shooting for a brown, you really insult those that try to offer friendly and helpful coamments.</td>', 'If you are shooting for a brown, you really insult those that try to offer friendly and helpful coamments.', '2007-03-03 06:17:31.000000', NULL, 1),
(3425010, 474846, 41554, '<td valign="top">Nice, good use of b/w. Could be better if those darn lines weren''t there, or if the DOF was shallower. Nice anyay.</td>', 'Nice, good use of b/w. Could be better if those darn lines weren''t there, or if the DOF was shallower. Nice anyay.', '2007-03-03 06:17:32.000000', NULL, 1),
(3425011, 475900, 55385, '<td valign="top">MMMMMMMM</td>', 'MMMMMMMM', '2007-03-03 06:18:06.000000', NULL, 1),
(3425013, 475090, 41554, '<td valign="top">What a great pic. If there was only the left or right ice "blocks" (right would be better IMHO) it would be a perfect 10 from me. Still I love the simbolism and technically it is very well done.</td>', 'What a great pic. If there was only the left or right ice "blocks" (right would be better IMHO) it would be a perfect 10 from me. Still I love the simbolism and technically it is very well done.', '2007-03-03 06:19:37.000000', NULL, 1),
(3425014, 475965, 41554, '<td valign="top">Great exposure control. A bit busy (lots of small branches etc.) but very nice.</td>', 'Great exposure control. A bit busy (lots of small branches etc.) but very nice.', '2007-03-03 06:20:28.000000', NULL, 1),
