(3425035, 475501, 41554, '<td valign="top">This type of shot (of mundane things) requires an extreme care in its preparation. The glass should be perfectly clean from little droplets, all reflections should be avoided / minimized, and a special attention to composition should be taken. Sorry, you didn''t do any of this.</td>', 'This type of shot (of mundane things) requires an extreme care in its preparation. The glass should be perfectly clean from little droplets, all reflections should be avoided / minimized, and a special attention to composition should be taken. Sorry, you didn''t do any of this.', '2007-03-03 06:43:29.000000', NULL, 1),
(3425037, 475985, 41554, '<td valign="top">A little bit more sharpness and this would really be great.</td>', 'A little bit more sharpness and this would really be great.', '2007-03-03 06:44:31.000000', NULL, 1),
(3425039, 474234, 41554, '<td valign="top">Great! Love the contrast between the "hot" sky and the ice. Well done.</td>', 'Great! Love the contrast between the "hot" sky and the ice. Well done.', '2007-03-03 06:46:40.000000', NULL, 1),
