(3427531, 476752, 21124, '<td valign="top">There is a bit of noise, isn''t there?</td>', 'There is a bit of noise, isn''t there?', '2007-03-04 11:08:13.000000', NULL, 1),
(3427534, 474121, 21124, '<td valign="top">So small...</td>', 'So small...', '2007-03-04 11:12:56.000000', NULL, 1),
(3427535, 474199, 21124, '<td valign="top">I like the color, but the composition is not that good.</td>', 'I like the color, but the composition is not that good.', '2007-03-04 11:13:51.000000', NULL, 1),
(3427537, 476824, 21124, '<td valign="top">The composition is not that interesting...</td>', 'The composition is not that interesting...', '2007-03-04 11:16:07.000000', NULL, 1),
(3427540, 472817, 21124, '<td valign="top">A bit noisy (too much compression?), and it seems that the focus is missed.</td>', 'A bit noisy (too much compression?), and it seems that the focus is missed.', '2007-03-04 11:16:56.000000', NULL, 1),
(3427549, 475829, 21124, '<td valign="top">I would have mirrored the photo. As most of the voters are used to read from left to right, it''s usually better to show movements also going from left to right.</td>', 'I would have mirrored the photo. As most of the voters are used to read from left to right, it''s usually better to show movements also going from left to right.', '2007-03-04 11:19:50.000000', NULL, 1),
(3427553, 476836, 21124, '<td valign="top">Nice concept and execution.<br/> <br/>Small problem: the mirror.<br/>I think that you are using a mirror that is reflecting from its lower surface and not its upper one, thus leading to the double reflection.<br/>To avoid it, I''d suggest you to either use a mirror reflecting from the upper surface (hard to find), or a black shiny epoxy piece (usually works fine for reflections)</td>', 'Nice concept and execution. Small problem: the mirror.I think that you are using a mirror that is reflecting from its lower surface and not its upper one, thus leading to the double reflection.To avoid it, I''d suggest you to either use a mirror reflecting from the upper surface (hard to find), or a black shiny epoxy piece (usually works fine for reflections)', '2007-03-04 11:23:14.000000', NULL, 1),
(3427554, 474381, 21124, '<td valign="top">I like the lights</td>', 'I like the lights', '2007-03-04 11:23:43.000000', NULL, 1),
(3427563, 475279, 21124, '<td valign="top">Very nice stock photography</td>', 'Very nice stock photography', '2007-03-04 11:27:52.000000', NULL, 1),
