(3427571, 475035, 21124, '<td valign="top">A bit oversharpened.</td>', 'A bit oversharpened.', '2007-03-04 11:30:23.000000', NULL, 1),
(3427573, 473898, 26669, '<td valign="top">sorry about this, and please dont take offence. This shot has poor lighting, poor focus, the main subject is not clear, i a, not sure what i am looking at other than poorly focused ice.</td>', 'sorry about this, and please dont take offence. This shot has poor lighting, poor focus, the main subject is not clear, i a, not sure what i am looking at other than poorly focused ice.', '2007-03-04 11:31:14.000000', NULL, 1),
(3427576, 475110, 57392, '<td valign="top">This is a nice capture,I feel that you took the photo from a nice angle/viewpoint.IMO Auto levels would realy boost the white of the snow,still making it a night scene.A little unsharp mask and crop to level the bridge IMO brings life to this photo.Good luck in this challenge.</td>', 'This is a nice capture,I feel that you took the photo from a nice angle/viewpoint.IMO Auto levels would realy boost the white of the snow,still making it a night scene.A little unsharp mask and crop to level the bridge IMO brings life to this photo.Good luck in this challenge.', '2007-03-04 11:32:07.000000', NULL, 1),
