(3437794, 475618, 5112, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Bear_Music:</b></div><hr/><i> Caught you tone mapping again, didn''t I? Lovely shot, Ursula. </i></td></tr></table> <br/> <br/>He, he, no, it''s NOT tone mapped.  Not even a bit :)  Fooled you, eh?  It''s adjustments in RAW.  The PSCS3 Beta RAW adjustment tool is quite interesting.<br/> <br/>ADDED:<br/> <br/>Fooled me instead :)  Shadow/highligh adjustments are essentially tone-mapping, but I jumped to the conclusion Bear meant Photomatix or similar.  Sorry :)<br/><br/><i>Message edited by author 2007-03-07 12:48:56.</i></td>', 'Originally posted by Bear_Music: Caught you tone mapping again, didn''t I? Lovely shot, Ursula.   He, he, no, it''s NOT tone mapped.  Not even a bit :)  Fooled you, eh?  It''s adjustments in RAW.  The PSCS3 Beta RAW adjustment tool is quite interesting. ADDED: Fooled me instead :)  Shadow/highligh adjustments are essentially tone-mapping, but I jumped to the conclusion Bear meant Photomatix or similar.  Sorry :)', '2007-03-07 11:28:26.000000', '2007-03-07 12:48:56.000000', 0),
(3437797, 476656, 66384, '<td valign="top">Absolutely spectacular! Well deserving of the blue ribbon. Congratulations on a wonderful image and on the 8.0 score - a huge accomplishment.</td>', 'Absolutely spectacular! Well deserving of the blue ribbon. Congratulations on a wonderful image and on the 8.0 score - a huge accomplishment.', '2007-03-07 11:29:17.000000', NULL, 0),
(3437830, 476398, 58736, '<td valign="top">Lucky lucky ice.</td>', 'Lucky lucky ice.', '2007-03-07 11:36:31.000000', NULL, 0),
(3437845, 474155, 52549, '<td valign="top">Beautful colours. WTG Jamie!</td>', 'Beautful colours. WTG Jamie!', '2007-03-07 11:39:06.000000', NULL, 0),
(3437867, 476656, 37104, '<td valign="top">I loved this shot, but I loved the outtake even more! Wow! Very nice work.</td>', 'I loved this shot, but I loved the outtake even more! Wow! Very nice work.', '2007-03-07 11:47:13.000000', NULL, 0),
(3437901, 476750, 23484, '<td valign="top">Neat shot there Don. I like the ice hanging from the ice.</td>', 'Neat shot there Don. I like the ice hanging from the ice.', '2007-03-07 11:55:21.000000', NULL, 0),
(3437905, 475581, 23484, '<td valign="top">A dieters dream come true.</td>', 'A dieters dream come true.', '2007-03-07 11:56:33.000000', NULL, 0),
(3437907, 476689, 66384, '<td valign="top">Such an interesting perspective. It''s very pleasing but difficult to understand at first. Parts of it seem upside down. The colors in the reflection are beautiful.</td>', 'Such an interesting perspective. It''s very pleasing but difficult to understand at first. Parts of it seem upside down. The colors in the reflection are beautiful.', '2007-03-07 11:57:07.000000', NULL, 0),
(3437915, 476689, 23484, '<td valign="top">This is a really cool shot. It has such a peaceful serene feel to it. I think it would look really neat without the fence.  I just think that kind of detracts a little.  The colors just all go together so nicely.</td>', 'This is a really cool shot. It has such a peaceful serene feel to it. I think it would look really neat without the fence.  I just think that kind of detracts a little.  The colors just all go together so nicely.', '2007-03-07 11:59:14.000000', NULL, 0),
(3437923, 474057, 66384, '<td valign="top">Lovely blue tone. The reflection and the diagonal line are great.</td>', 'Lovely blue tone. The reflection and the diagonal line are great.', '2007-03-07 12:03:21.000000', NULL, 0),
(3438060, 476656, 14476, '<td valign="top">Spectacular. Both the image and the score.  Congratulations.</td>', 'Spectacular. Both the image and the score.  Congratulations.', '2007-03-07 12:36:55.000000', NULL, 0),
